32	const pendingReviewMarkerFilename = "review-pending.json"
33	
34	// PendingReviewMarker is written by `entire review` before spawning the agent.
35	// The next agent session's UserPromptSubmit hook reads it, tags the session
36	// kind/review-skills, then clears the marker (so a second review run doesn't
37	// inherit state from the first).
38	type PendingReviewMarker struct {
39		AgentName   string    `json:"agent_name"`
40		Skills      []string  `json:"skills"`
41		StartingSHA string    `json:"starting_sha"`
42		StartedAt   time.Time `json:"started_at"`
43	}
44	
45	func pendingMarkerPath() (string, error) {
46		commonDir, err := session.GetGitCommonDir(context.Background())
47		if err != nil {
48			return "", fmt.Errorf("locate git common dir: %w", err)
49		}
50		return filepath.Join(commonDir, session.SessionStateDirName, pendingReviewMarkerFilename), nil
51	}
52	
53	// WritePendingReviewMarker persists the marker. Overwrites any existing marker
54	// — callers detect concurrent reviews via ReadPendingReviewMarker before this.
55	func WritePendingReviewMarker(m PendingReviewMarker) error {
56		path, err := pendingMarkerPath()
57		if err != nil {
58			return err
59		}
60		if err := os.MkdirAll(filepath.Dir(path), 0o750); err != nil {
61			return fmt.Errorf("create sessions dir: %w", err)
62		}
63		data, err := json.MarshalIndent(m, "", "  ")
64		if err != nil {
65			return fmt.Errorf("marshal marker: %w", err)
66		}
67		if err := os.WriteFile(path, data, 0o600); err != nil {
68			return fmt.Errorf("write marker: %w", err)
69		}
70		return nil
71	}
72	
73	// ReadPendingReviewMarker returns the marker if one exists.
74	// ok=false with err=nil indicates "no pending review."
75	func ReadPendingReviewMarker() (PendingReviewMarker, bool, error) {
76		path, err := pendingMarkerPath()
77		if err != nil {
78			return PendingReviewMarker{}, false, err
79		}
80		data, err := os.ReadFile(path) //nolint:gosec // path derived from git dir
81		if errors.Is(err, os.ErrNotExist) {
82			return PendingReviewMarker{}, false, nil
83		}
84		if err != nil {
85			return PendingReviewMarker{}, false, fmt.Errorf("read marker: %w", err)
86		}
87		var m PendingReviewMarker
88		if err := json.Unmarshal(data, &m); err != nil {
89			return PendingReviewMarker{}, false, fmt.Errorf("parse marker: %w", err)
90		}
91		return m, true, nil
92	}
93	
94	// ClearPendingReviewMarker removes the marker. Missing file is not an error.
95	func ClearPendingReviewMarker() error {
96		path, err := pendingMarkerPath()
97		if err != nil {
98			return err
99		}
100		if err := os.Remove(path); err != nil && !errors.Is(err, os.ErrNotExist) {
101			return fmt.Errorf("remove marker: %w", err)
102		}
103		return nil
104	}
