394	// composeReviewPrompt builds the initial prompt the agent receives.
395	func composeReviewPrompt(skills []string) string {
396		var sb strings.Builder
397		sb.WriteString("Please run these review skills in order:\n")
398		for i, skill := range skills {
399			fmt.Fprintf(&sb, "  %d. %s\n", i+1, skill)
400		}
401		return sb.String()
402	}
